def display_name(value):
    return " ".join(value.split())


def visible_names(members):
    """Return active display names sorted case-insensitively and stably."""
    names = []
    for member in members:
        if member.get("archived", False):
            continue
        name = display_name(member["name"])
        if name:
            names.append(name)
    names.sort(key=str.casefold)
    return names


def member_count(members):
    return len(visible_names(members))

